/**
 * Determines whether an automatic row limit should be appended to a SQL query.
 *
 * An auto limit is only appended when the query is a single, simple SELECT
 * statement that doesn't already constrain its result set. We deliberately bail
 * out on anything ambiguous (multiple statements, comments, existing LIMIT) to
 * avoid altering the semantics of the user's query.
 */
export function checkIfAppendLimitRequired(sql: string, limit: number = 0) {
  // Strip trailing whitespace and semicolons so a single trailing `;` doesn't
  // get counted as a statement separator.
  const cleanedSql = sql.replace(/[\s;]+$/, '')

  const isSelect = /^\s*select/i.test(cleanedSql)
  const containsLimit = /\blimit\b/i.test(cleanedSql)
  // Any remaining semicolon after trimming the trailing one indicates more than
  // one statement.
  const containsMultipleStatements = cleanedSql.includes(';')
  // Comments could hide a LIMIT or additional statements, so treat them as a
  // false positive and skip the auto limit.
  const containsComments = cleanedSql.includes('--')

  const appendAutoLimit =
    limit > 0 &&
    isSelect &&
    !containsLimit &&
    !containsMultipleStatements &&
    !containsComments

  return { cleanedSql, appendAutoLimit }
}

/**
 * Removes any trailing semicolons from the SQL and appends a `limit {n};`
 * clause, ensuring the result ends with exactly one semicolon.
 */
export function suffixWithLimit(sql: string, limit: number) {
  const cleanedSql = sql.replace(/[\s;]+$/, '')
  return `${cleanedSql} limit ${limit};`
